async function main(input) {
  const [me] = await records.list("llm_learners", { limit: 1 });
  if (!me) return { notify: "Pick Python or JavaScript first, on the course page." };
  const language = me.language;
  let lesson = String((input && input.lesson) || "");
  if (lesson === "next") {
    const done = new Set((await records.list("llm_work", { where: "=passed == true && language == params.language", params: { language }, limit: 100 })).map((row) => row.lesson));
    lesson = ORDER.find((key) => !done.has(key)) || "";
    if (!lesson) return { go: { screen: "model", params: { id: me.id } } };
  }
  if (!STARTERS[lesson]) return { notify: "There's no such lesson." };
  const [work] = await records.list("llm_work", { where: "=lesson == params.lesson && language == params.language", params: { lesson, language }, limit: 1 });
  const id = work ? work.id : (await records.create("llm_work", { lesson, language, code: STARTERS[lesson][language], passed: false, tries: 0 })).id;
  return { go: { screen: lesson, params: { work: id } } };
}

// "Check my answer": the person's code runs on the computer with the lesson's checks (the app's files: course/), after
// their code of the lessons they've passed (lib/), so a lesson can use what came before. Their code, the output, and
// whether it passed stay on their own work for the lesson; the code that last passed builds their model.
const RUN = {
  Python: { file: "answer.py", lib: ".py", check: "python3 course/check.py ", train: "python3 course/model.py train 60", chat: "python3 course/model.py chat" },
  JavaScript: { file: "answer.js", lib: ".js", check: "node course/check.js ", train: "node course/model.js train 60", chat: "node course/model.js chat" }
};

async function main(input) {
  const work = await records.get("llm_work", String(input.work));
  if (!work) return { notify: "That lesson's work is no longer there." };
  const code = String(input.code ?? work.code ?? "");
  const run = RUN[work.language] || RUN.Python;
  const files = { [run.file]: code };
  const earlier = await records.list("llm_work", { where: "=passed == true && language == params.language && lesson != params.lesson", params: { language: work.language, lesson: work.lesson }, limit: 100 });
  for (const row of earlier) if (row.passed_code) files["lib/" + row.lesson + run.lib] = row.passed_code;
  const result = await computer.run({ command: run.check + work.lesson, files, seconds: 15 });
  const passed = result.exitCode === 0 && !result.timedOut;
  const output = result.timedOut
    ? result.output + "\n⏱️ Your code ran for more than 15 seconds, so it was stopped: is there a loop that never ends?"
    : result.output;
  await records.update("llm_work", work.id, {
    code,
    result: output.slice(0, 20000),
    passed: passed || work.passed === true,
    tries: (work.tries || 0) + 1,
    checked: new Date().toISOString(),
    ...(passed ? { passed_code: code } : {})
  });
  if (passed) return { celebrate: "🎉 Every check passed!" };
  const last = output.trim().split("\n").pop() || "";
  return { notify: /checks passed/.test(last) ? last + " See below what to fix." : "Not yet: see below what to fix." };
}

