async function main() {
  const [me] = await records.list("llm_learners", { limit: 1 });
  if (!me) return { notify: "Pick Python or JavaScript first, on the course page." };
  return { go: { screen: "model", params: { id: me.id } } };
}

// "Train my model": the book's text and the person's code of the lessons they've passed go to the computer, which
// trains their model (a minute at most) and keeps it as a file on their own learner record, with what it said.
const RUN = {
  Python: { file: "answer.py", lib: ".py", check: "python3 course/check.py ", train: "python3 course/model.py train 60", chat: "python3 course/model.py chat" },
  JavaScript: { file: "answer.js", lib: ".js", check: "node course/check.js ", train: "node course/model.js train 60", chat: "node course/model.js chat" }
};
function changedIds(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

async function main(input) {
  const trained = [];
  for (const id of changedIds(input)) {
    const me = await records.get("llm_learners", id);
    if (!me || me.status !== "Training") continue;
    if (!me.book) {
      await records.update("llm_learners", id, { status: "Problem", note: "Add a book first: a text, Word or PDF file." });
      continue;
    }
    let book;
    try {
      book = await docs.text({ record: { table: "llm_learners", id }, field: "book" });
    } catch (error) {
      await records.update("llm_learners", id, { status: "Problem", note: "I couldn't read the book: " + error.message });
      continue;
    }
    const run = RUN[me.language] || RUN.Python;
    const files = { "book.txt": book.text.slice(0, 150000) };
    const passed = await records.list("llm_work", { where: "=whose == params.who && passed == true && language == params.language", params: { who: me.whose, language: me.language }, limit: 100 });
    for (const row of passed) if (row.passed_code) files["lib/" + row.lesson + run.lib] = row.passed_code;
    const result = await computer.run({ command: run.train, files, seconds: 240, keep: { "model.json": { table: "llm_learners", id, field: "model" } } });
    const mine = passed.length
      ? "It used your own code from " + passed.length + (passed.length === 1 ? " lesson" : " lessons") + " and the course's for the rest."
      : "It used the course's code: pass lessons and it uses yours.";
    if (result.exitCode === 0 && result.kept["model.json"]) {
      await records.update("llm_learners", id, { status: "Ready", note: result.output.trim() + "\n" + mine, trained: new Date().toISOString(), model_language: me.language });
      trained.push(id);
    } else {
      await records.update("llm_learners", id, { status: "Problem", note: (result.timedOut ? "Training took too long. " : "Training stopped. ") + result.output.trim().slice(-2000) });
    }
  }
  return { trained };
}

// A chat with the person's own model: their words and its reply are their own messages. Their model (the file on their
// learner record) runs on the computer with their passed lessons' code, in the language it was trained in.
const RUN = {
  Python: { file: "answer.py", lib: ".py", check: "python3 course/check.py ", train: "python3 course/model.py train 60", chat: "python3 course/model.py chat" },
  JavaScript: { file: "answer.js", lib: ".js", check: "node course/check.js ", train: "node course/model.js train 60", chat: "node course/model.js chat" }
};

async function main(input) {
  const me = await records.get("llm_learners", String(input.learner));
  const text = String((input && input.text) || "").trim();
  if (!text) return { notify: "Say something first." };
  if (!me || !me.model) return { notify: "Train your model on a book first." };
  const language = me.model_language || me.language;
  const run = RUN[language] || RUN.Python;
  const files = { "message.txt": text.slice(0, 2000) };
  const passed = await records.list("llm_work", { where: "=passed == true && language == params.language", params: { language }, limit: 100 });
  for (const row of passed) if (row.passed_code) files["lib/" + row.lesson + run.lib] = row.passed_code;
  const now = Date.now();
  await records.create("llm_messages", { who: "You", text: text.slice(0, 2000), at: new Date(now).toISOString() });
  const result = await computer.run({ command: run.chat, files, recordFiles: { "model.json": { table: "llm_learners", id: me.id, field: "model" } }, seconds: 20 });
  const said = result.exitCode === 0 ? result.output.trim() : "(It couldn't answer: " + (result.output.trim().split("\n").pop() || "it stopped") + ")";
  await records.create("llm_messages", { who: "Model", text: (said || "…").slice(0, 4000), at: new Date(now + 1).toISOString() });
  return {};
}

// The person's own messages, put away (each person's own: nobody else's are reached).
async function main() {
  const messages = await records.list("llm_messages", { limit: 45 });
  for (const message of messages) await records.markObsolete("llm_messages", message.id);
  return { notify: "Your chat is cleared." };
}

