# Checks your code for a lesson: python3 course/check.py <lesson>. Your earlier lessons' code (lib/) and the course's
# own (reference.py) are loaded first, so a lesson can use what came before; then yours (answer.py) and its checks.
import math
import os
import sys

sys.dont_write_bytecode = True
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import tests  # noqa: E402


class Names:
    """Your functions, by name, as the checks call them."""

    def __init__(self, space):
        self.__dict__["_space"] = space

    def __getattr__(self, name):
        if name not in self._space:
            raise NameError(f"there's no function called {name}")
        return self._space[name]


def close(got, expected):
    if isinstance(expected, bool) or isinstance(got, bool):
        return got is expected
    if isinstance(expected, (int, float)) and isinstance(got, (int, float)):
        return math.isclose(got, expected, rel_tol=1e-6, abs_tol=1e-6)
    if isinstance(expected, (list, tuple)) and isinstance(got, (list, tuple)):
        return len(got) == len(expected) and all(close(a, b) for a, b in zip(got, expected))
    if isinstance(expected, dict) and isinstance(got, dict):
        return set(got) == set(expected) and all(close(got[key], expected[key]) for key in expected)
    return got == expected


def shown(value):
    if isinstance(value, float):
        return f"{value:.6g}"
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(shown(item) for item in value) + "]"
    return repr(value)


class Checker:
    def __init__(self):
        self.passed = 0
        self.total = 0

    def same(self, what, work, expected):
        self.total += 1
        try:
            got = work()
        except Exception as error:  # noqa: BLE001 - a learner's mistake is shown, never raised
            print(f"❌ {what} should be {shown(expected)}, but it stopped: {type(error).__name__}: {error}")
            return
        if close(got, expected):
            self.passed += 1
            print(f"✅ {what} is {shown(expected)}")
        else:
            print(f"❌ {what} should be {shown(expected)}, but it gave {shown(got)}")


def load(space, path, name):
    with open(path, encoding="utf-8") as file:
        exec(compile(file.read(), name, "exec"), space)  # noqa: S102 - the learner's own code, in the sandbox


def main():
    key = sys.argv[1]
    needs, run = tests.LESSONS[key]
    space = {"__name__": "mylib"}
    load(space, os.path.join(HERE, "reference.py"), "reference.py")
    for name in sorted(os.listdir("lib")) if os.path.isdir("lib") else []:
        try:
            load(space, os.path.join("lib", name), name)
        except Exception:  # noqa: BLE001 - an earlier lesson's code that no longer runs is left out
            pass
    before = {name: space.get(name) for name in needs}
    try:
        load(space, "answer.py", "your code")
    except SyntaxError as error:
        print(f"❌ Python can't read your code: {error.msg} (line {error.lineno}).")
        return 1
    except Exception as error:  # noqa: BLE001
        print(f"❌ Your code stopped before the checks: {type(error).__name__}: {error}")
        return 1
    missing = [name for name in needs if space.get(name) is before[name]]
    if missing:
        print("❌ Write " + " and ".join(f"def {name}(…)" for name in missing) + " in your code: the checks look for it.")
        return 1
    checker = Checker()
    run(Names(space), checker)
    print("")
    if checker.passed == checker.total:
        print(f"🎉 {checker.passed} of {checker.total} checks passed.")
        return 0
    print(f"{checker.passed} of {checker.total} checks passed.")
    return 1


