// Your little language model: node course/model.js train [seconds] [steps] | chat
//   train: learns from book.txt and writes model.json (a minute at most, fewer steps for a short text).
//   chat:  continues message.txt in the book's style with model.json, and prints the reply.
// It is made of your functions (lib/, the lessons you've passed) and the course's (reference.js) for the rest: the
// characters (vocabulary, encode, decode, windows) and, when it talks, softmax, sample and attention. Training runs the
// same maths in plain loops over typed arrays, so it's fast: a context of K characters, each an embedding (E) plus its
// place (P); attention from the last character over the context, added to it; then one layer (Wo, b) gives a score for
// every character.
const fs = require("node:fs");
const { library } = require("./library.js");

const K = 8;
const D = 24;
const MAX_CHARS = 150000;

const cleaned = (text) =>
  text.replace(/\r\n?/g, "\n").replace(/\t/g, " ").split("\n").map((line) => line.split(/\s+/).filter(Boolean).join(" ")).join("\n")
    .replace(/\n{3,}/g, "\n\n").trim().slice(0, MAX_CHARS);

/** A random number generator that gives the same numbers every time (mulberry32). */
function seeded(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function train(seconds, most) {
  const lib = library();
  const text = cleaned(fs.readFileSync("book.txt", "utf8"));
  if (text.length < 200) {
    console.log("The book is too short to learn from: give it a book or a long text (a few pages at least).");
    return 1;
  }
  const vocab = lib.vocabulary(text);
  const ids = lib.encode(text, vocab);
  const pairs = lib.windows(ids, K);
  const V = vocab.length;
  const random = seeded(7);
  const normal = () => Math.sqrt(-2 * Math.log(random() + 1e-12)) * Math.cos(2 * Math.PI * random()) * 0.3;
  const params = {
    E: Float64Array.from({ length: V * D }, normal),
    P: Float64Array.from({ length: K * D }, normal),
    Wo: Float64Array.from({ length: D * V }, normal),
    b: new Float64Array(V)
  };
  const grads = Object.fromEntries(Object.entries(params).map(([name, value]) => [name, new Float64Array(value.length)]));
  const moments = Object.fromEntries(Object.entries(params).map(([name, value]) => [name, [new Float64Array(value.length), new Float64Array(value.length)]]));
  const batch = 32;
  // A short text needs fewer steps: about one an example, from 1,500 up to the most asked for.
  most = Math.min(most, Math.max(1500, pairs.length));
  const rate = 0.01;
  const root = Math.sqrt(D);
  const x = new Float64Array(K * D);
  const dx = new Float64Array(K * D);
  const h = new Float64Array(D);
  const dh = new Float64Array(D);
  const q = new Float64Array(D);
  const a = new Float64Array(K);
  const p = new Float64Array(V);
  const started = Date.now();
  let steps = 0;
  let first = null;
  let last = null;
  while ((Date.now() - started) / 1000 < seconds && steps < most) {
    for (const grad of Object.values(grads)) grad.fill(0);
    let total = 0;
    for (let n = 0; n < batch; n += 1) {
      const [context, target] = pairs[Math.floor(random() * pairs.length)];
      for (let i = 0; i < K; i += 1) for (let d = 0; d < D; d += 1) x[i * D + d] = params.E[context[i] * D + d] + params.P[i * D + d];
      for (let d = 0; d < D; d += 1) q[d] = x[(K - 1) * D + d];
      let top = -Infinity;
      for (let i = 0; i < K; i += 1) {
        let s = 0;
        for (let d = 0; d < D; d += 1) s += x[i * D + d] * q[d];
        a[i] = s / root;
        top = Math.max(top, a[i]);
      }
      let whole = 0;
      for (let i = 0; i < K; i += 1) whole += (a[i] = Math.exp(a[i] - top));
      for (let i = 0; i < K; i += 1) a[i] /= whole;
      for (let d = 0; d < D; d += 1) {
        let s = q[d];
        for (let i = 0; i < K; i += 1) s += a[i] * x[i * D + d];
        h[d] = s;
      }
      top = -Infinity;
      for (let j = 0; j < V; j += 1) {
        let s = params.b[j];
        for (let d = 0; d < D; d += 1) s += h[d] * params.Wo[d * V + j];
        p[j] = s;
        top = Math.max(top, s);
      }
      whole = 0;
      for (let j = 0; j < V; j += 1) whole += (p[j] = Math.exp(p[j] - top));
      for (let j = 0; j < V; j += 1) p[j] /= whole;
      total += -Math.log(p[target] + 1e-12);
      p[target] -= 1;
      dh.fill(0);
      for (let j = 0; j < V; j += 1) {
        const g = p[j] / batch;
        grads.b[j] += g;
        for (let d = 0; d < D; d += 1) {
          grads.Wo[d * V + j] += h[d] * g;
          dh[d] += params.Wo[d * V + j] * g;
        }
      }
      // h = Σ a_i x_i + q: back through the attention and the softmax of its scores.
      let mix = 0;
      const da = new Float64Array(K);
      for (let i = 0; i < K; i += 1) {
        let s = 0;
        for (let d = 0; d < D; d += 1) {
          dx[i * D + d] = a[i] * dh[d];
          s += x[i * D + d] * dh[d];
        }
        da[i] = s;
        mix += a[i] * s;
      }
      const dq = Float64Array.from(dh);
      for (let i = 0; i < K; i += 1) {
        const ds = (a[i] * (da[i] - mix)) / root;
        for (let d = 0; d < D; d += 1) {
          dq[d] += ds * x[i * D + d];
          dx[i * D + d] += ds * q[d];
        }
      }
      for (let d = 0; d < D; d += 1) dx[(K - 1) * D + d] += dq[d];
      for (let i = 0; i < K; i += 1) {
        for (let d = 0; d < D; d += 1) {
          grads.E[context[i] * D + d] += dx[i * D + d];
          grads.P[i * D + d] += dx[i * D + d];
        }
      }
    }
    const value = total / batch;
    first = first === null ? value : first;
    last = last === null ? value : 0.98 * last + 0.02 * value;
    steps += 1;
    for (const [name, value] of Object.entries(params)) {
      const [m, v] = moments[name];
      const grad = grads[name];
      for (let i = 0; i < value.length; i += 1) {
        m[i] = 0.9 * m[i] + 0.1 * grad[i];
        v[i] = 0.999 * v[i] + 0.001 * grad[i] * grad[i];
        value[i] -= (rate * (m[i] / (1 - 0.9 ** steps))) / (Math.sqrt(v[i] / (1 - 0.999 ** steps)) + 1e-8);
      }
    }
  }
  const rows = (flat, width) => Array.from({ length: flat.length / width }, (_, row) => Array.from(flat.slice(row * width, (row + 1) * width), (n) => Math.round(n * 1e5) / 1e5));
  fs.writeFileSync("model.json", JSON.stringify({ vocab, K, D, E: rows(params.E, D), P: rows(params.P, D), Wo: rows(params.Wo, V), b: rows(params.b, V)[0] }));
  console.log(`Read ${text.length.toLocaleString("en")} characters: ${V} different ones, ${pairs.length.toLocaleString("en")} examples.`);
  console.log(`Trained for ${steps.toLocaleString("en")} steps in ${Math.round((Date.now() - started) / 1000)} s: the loss went from ${first.toFixed(2)} to ${last.toFixed(2)}.`);
  return 0;
}

function chat() {
  const lib = library();
  const model = JSON.parse(fs.readFileSync("model.json", "utf8"));
  const message = fs.readFileSync("message.txt", "utf8");
  const { vocab, K: k, E, P, b } = model;
  const outRows = lib.transpose(model.Wo);
  const known = new Set(vocab);
  const space = known.has(" ") ? " " : vocab[0];
  const prompt = [...message.trim()].filter((char) => known.has(char)).join("") || space;
  const ids = lib.encode((space.repeat(k) + prompt + space).slice(-k), vocab);
  const random = seeded(message.length);
  const reply = [];
  for (let n = 0; n < 240; n += 1) {
    const context = ids.slice(-k);
    const rows = context.map((id, place) => lib.add(E[id], P[place]));
    const h = lib.add(lib.attention(rows[rows.length - 1], rows, rows), rows[rows.length - 1]);
    const logits = lib.add(lib.matvec(outRows, h), b);
    const next = lib.sample(lib.softmax(logits.map((value) => value / 0.8)), random());
    ids.push(next);
    reply.push(next);
    const text = lib.decode(reply, vocab);
    if (text.length > 60 && ".!?\n".includes(text[text.length - 1])) break;
  }
  console.log(lib.decode(reply, vocab).trim());
  return 0;
}

const [command, seconds, steps] = process.argv.slice(2);
if (command === "train") process.exitCode = train(Number(seconds) || 60, Number(steps) || 12000);
else if (command === "chat") process.exitCode = chat();
else {
  console.log("model.js train [seconds] [steps] | chat");
  process.exitCode = 2;
}

