// The course's own solutions, one lesson after another. Your code takes their place lesson by lesson: the checks and
// your model use your functions where you've written them, and these where you haven't yet.

// --- l01 ---
function total(numbers) {
  let result = 0;
  for (const number of numbers) result = result + number;
  return result;
}

function count(items, wanted) {
  let found = 0;
  for (const item of items) {
    if (item === wanted) found = found + 1;
  }
  return found;
}

// --- l02 ---
function tally(text) {
  const counts = {};
  for (const char of text) counts[char] = (counts[char] || 0) + 1;
  return counts;
}

// --- l03 ---
function mean(xs) {
  return xs.reduce((sum, x) => sum + x, 0) / xs.length;
}

function variance(xs) {
  const middle = mean(xs);
  return xs.reduce((sum, x) => sum + (x - middle) ** 2, 0) / xs.length;
}

// --- l04 ---
function normalize(counts) {
  const whole = counts.reduce((sum, c) => sum + c, 0);
  return counts.map((c) => c / whole);
}

// --- l05 ---
function sample(probs, r) {
  let running = 0;
  for (let index = 0; index < probs.length; index += 1) {
    running = running + probs[index];
    if (r < running) return index;
  }
  return probs.length - 1;
}

// --- l06 ---
function dot(a, b) {
  let sum = 0;
  for (let i = 0; i < a.length; i += 1) sum = sum + a[i] * b[i];
  return sum;
}

function add(a, b) {
  return a.map((x, i) => x + b[i]);
}

function scale(a, k) {
  return a.map((x) => x * k);
}

// --- l07 ---
function matvec(m, v) {
  return m.map((row) => dot(row, v));
}

function transpose(m) {
  return m[0].map((_, column) => m.map((row) => row[column]));
}

// --- l08 ---
function softmax(xs) {
  const top = Math.max(...xs);
  const exps = xs.map((x) => Math.exp(x - top));
  const whole = exps.reduce((sum, e) => sum + e, 0);
  return exps.map((e) => e / whole);
}

// --- l09 ---
function loss(probs, target) {
  return -Math.log(probs[target]);
}

function step(weights, grads, rate) {
  return weights.map((w, i) => w - rate * grads[i]);
}

// --- l10 ---
function vocabulary(text) {
  return [...new Set(text)].sort();
}

function encode(text, vocab) {
  const index = new Map(vocab.map((char, i) => [char, i]));
  return [...text].map((char) => index.get(char));
}

function decode(ids, vocab) {
  return ids.map((i) => vocab[i]).join("");
}

// --- l11 ---
function bigrams(ids, size) {
  const counts = Array.from({ length: size }, () => new Array(size).fill(0));
  for (let i = 0; i + 1 < ids.length; i += 1) counts[ids[i]][ids[i + 1]] += 1;
  return counts;
}

function following(counts, a) {
  const row = counts[a];
  const whole = row.reduce((sum, c) => sum + c, 0) + row.length;
  return row.map((c) => (c + 1) / whole);
}

// --- l12 ---
function generate(counts, start, rs) {
  const ids = [start];
  for (const r of rs) ids.push(sample(following(counts, ids[ids.length - 1]), r));
  return ids;
}

// --- l13 ---
function predict(weights, a) {
  return softmax(weights[a]);
}

function learn(weights, a, b, rate) {
  const probs = predict(weights, a);
  const row = weights[a].map((w, j) => w - rate * (probs[j] - (j === b ? 1 : 0)));
  return weights.map((r, i) => (i === a ? row : [...r]));
}

// --- l14 ---
function attention(query, keys, values) {
  const size = query.length;
  const weights = softmax(keys.map((key) => dot(query, key) / Math.sqrt(size)));
  let out = new Array(values[0].length).fill(0);
  weights.forEach((w, i) => {
    out = add(out, scale(values[i], w));
  });
  return out;
}

function windows(ids, k) {
  const pairs = [];
  for (let i = k; i < ids.length; i += 1) pairs.push([ids.slice(i - k, i), ids[i]]);
  return pairs;
}

