# The course's own solutions, one lesson after another. Your code takes their place lesson by lesson: the checks and
# your model use your functions where you've written them, and these where you haven't yet.
import math

# --- l01 ---
def total(numbers):
    result = 0
    for number in numbers:
        result = result + number
    return result

def count(items, wanted):
    found = 0
    for item in items:
        if item == wanted:
            found = found + 1
    return found

# --- l02 ---
def tally(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts

# --- l03 ---
def mean(xs):
    return sum(xs) / len(xs)

def variance(xs):
    middle = mean(xs)
    return sum((x - middle) ** 2 for x in xs) / len(xs)

# --- l04 ---
def normalize(counts):
    whole = sum(counts)
    return [c / whole for c in counts]

# --- l05 ---
def sample(probs, r):
    running = 0.0
    for index, p in enumerate(probs):
        running = running + p
        if r < running:
            return index
    return len(probs) - 1

# --- l06 ---
def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def add(a, b):
    return [x + y for x, y in zip(a, b)]

def scale(a, k):
    return [x * k for x in a]

# --- l07 ---
def matvec(m, v):
    return [dot(row, v) for row in m]

def transpose(m):
    return [list(column) for column in zip(*m)]

# --- l08 ---
def softmax(xs):
    top = max(xs)
    exps = [math.exp(x - top) for x in xs]
    whole = sum(exps)
    return [e / whole for e in exps]

# --- l09 ---
def loss(probs, target):
    return -math.log(probs[target])

def step(weights, grads, rate):
    return [w - rate * g for w, g in zip(weights, grads)]

# --- l10 ---
def vocabulary(text):
    return sorted(set(text))

def encode(text, vocab):
    index = {char: i for i, char in enumerate(vocab)}
    return [index[char] for char in text]

def decode(ids, vocab):
    return "".join(vocab[i] for i in ids)

# --- l11 ---
def bigrams(ids, size):
    counts = [[0] * size for _ in range(size)]
    for a, b in zip(ids, ids[1:]):
        counts[a][b] = counts[a][b] + 1
    return counts

def following(counts, a):
    row = counts[a]
    whole = sum(row) + len(row)
    return [(c + 1) / whole for c in row]

# --- l12 ---
def generate(counts, start, rs):
    ids = [start]
    for r in rs:
        ids.append(sample(following(counts, ids[-1]), r))
    return ids

# --- l13 ---
def predict(weights, a):
    return softmax(weights[a])

def learn(weights, a, b, rate):
    probs = predict(weights, a)
    row = [w - rate * (p - (1 if j == b else 0)) for j, (w, p) in enumerate(zip(weights[a], probs))]
    return [row if i == a else list(r) for i, r in enumerate(weights)]

# --- l14 ---
def attention(query, keys, values):
    size = len(query)
    weights = softmax([dot(query, key) / math.sqrt(size) for key in keys])
    out = [0.0] * len(values[0])
    for w, value in zip(weights, values):
        out = add(out, scale(value, w))
    return out

def windows(ids, k):
    return [[ids[i - k:i], ids[i]] for i in range(k, len(ids))]

